import { GRUtils } from './../../../slots/utils/GRUtils';
import { bind } from '@game-studio/bindings';
import { GRModel } from '../../../slots/core/model/GRModel';
import { GCService } from '../GCService';
import { CascadeState } from '../types';

export class GCModel extends GRModel {

    public readonly CASCADE_STATE: string = '_cascadeState';

    @bind() public cascadeComplete: boolean = false;
    @bind() public cascadeLocations: number[][] = [];
    @bind() public cascadeOutcome: number[][] = [];

    private _cascadeState: number[] = [];

    protected _service: GCService;

    constructor(service: GCService) {
        super(service);
        this._service = service;
    }

    public invalidateSingleCascadeState(stateIndex: number, newState: CascadeState): void {
        const states: number[] = [...this.cascadeState];
        states[stateIndex] = newState;
        this.cascadeState = states;
        if (newState === CascadeState.NOT_CASCADING) {
            this.isCascadeComplete();
        }
    }

    private isCascadeComplete(): void {
        if (this.cascadeComplete) {
            return;
        }
        // check if states are all set to not cascading.
        if (GRUtils.unanimousStateOf(this.cascadeState) !== CascadeState.NOT_CASCADING) {
            return;
        }
        this.cascadeComplete = true;
        this._service.eventFire.serviceEvent.ON_CASCADE_COMPLETE();
    }

    public set cascadeState(val: number[]) {
        this._cascadeState = val;
        this._service.eventFire.serviceEvent.ON_CASCADE_STATE_CHANGED();
        this.invalidate(this.CASCADE_STATE);
    }

    public get cascadeState(): number[] {
        return (this._cascadeState);
    }
}